def nthMagical(n, a, b):
    from math import gcd
    lcm = a // gcd(a, b) * b

    def count(x):
        return x // a + x // b - x // lcm

    lo, hi = 1, n * min(a, b)
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= n:
            hi = mid
        else:
            lo = mid + 1
    return lo % (10 ** 9 + 7)
